#include <chrono>
#include <cstdint>
#include <iostream>
#include <poll.h>
#include <sstream>
#include <string>
#include "bike/node.hpp"
#include "bike/supervisor.hpp"
#include "diagnostic_logger.hpp"
#include "self_test_runner.hpp"
#include "posix_serial_transport.hpp"
namespace {
std::uint32_t now_ms(){using namespace std::chrono;return static_cast<std::uint32_t>(duration_cast<milliseconds>(steady_clock::now().time_since_epoch()).count());}
const char* name(bike::NodeAddress a){switch(a){case bike::NodeAddress::MainComputer:return "MAIN";case bike::NodeAddress::DiagnosticComputer:return "DIAG";case bike::NodeAddress::Northbridge:return "NORTHBRIDGE";case bike::NodeAddress::Lighting:return "LIGHTING";case bike::NodeAddress::Security:return "SECURITY";case bike::NodeAddress::Broadcast:return "BROADCAST";}return "UNKNOWN";}
const char* result(diag::TestResult r){switch(r){case diag::TestResult::Pass:return "PASS";case diag::TestResult::Warn:return "WARN";case diag::TestResult::Fail:return "FAIL";default:return "PENDING";}}
bool request(bike::BikeNode& n,bike::NodeAddress dst,bike::MessageType type,std::uint32_t now){bike::Packet p{};p.destination=dst;p.type=type;return n.send(p,now,false);}
std::string decode(const bike::Packet& p){std::ostringstream o;o<<"type=0x"<<std::hex<<unsigned(static_cast<std::uint8_t>(p.type))<<std::dec<<" seq="<<p.sequence<<" len="<<p.length;if(p.type==bike::MessageType::SecurityState&&p.length>=6)o<<" mode="<<unsigned(p.payload[0])<<" inhibit="<<unsigned(p.payload[1])<<" alarm="<<unsigned(p.payload[2])<<" engine="<<unsigned(p.payload[5]);else if(p.type==bike::MessageType::StateUpdate&&p.length>=8)o<<" left="<<unsigned(p.payload[1])<<" right="<<unsigned(p.payload[3])<<" brake="<<unsigned(p.payload[5])<<" high="<<unsigned(p.payload[7]);return o.str();}
void report(diag::SelfTestRunner& test){if(!test.report_ready())return;unsigned pass=0,warn=0,fail=0;std::cout<<"SELF-TEST REPORT\n";for(const auto& i:test.items()){std::cout<<"  "<<name(i.node)<<": "<<result(i.result)<<" "<<i.elapsed<<"ms "<<i.detail<<"\n";if(i.result==diag::TestResult::Pass)++pass;else if(i.result==diag::TestResult::Warn)++warn;else ++fail;}std::cout<<"SUMMARY pass="<<pass<<" warn="<<warn<<" fail="<<fail<<" total="<<test.total_elapsed()<<"ms\n";test.consume_report();}
bool parse_node(const std::string& s,bike::NodeAddress& a){if(s=="northbridge")a=bike::NodeAddress::Northbridge;else if(s=="lighting")a=bike::NodeAddress::Lighting;else if(s=="security")a=bike::NodeAddress::Security;else return false;return true;}
}
int main(int argc,char** argv){const std::string dev=argc>1?argv[1]:"/dev/serial0";PosixSerialTransport transport;if(!transport.open_device(dev,115200)){std::cerr<<"Unable to open "<<dev<<"\n";return 1;}bike::BikeNode node(bike::NodeAddress::DiagnosticComputer,transport);bike::NetworkSupervisor supervisor(node);diag::DiagnosticLogger logger;diag::SelfTestRunner test;if(!logger.open("motorcycle-diagnostics.csv"))std::cerr<<"Warning: CSV logging unavailable\n";supervisor.send_discovery(now_ms());std::cout<<"Motorcycle diagnostics on "<<dev<<"\nCommands: scan, inventory, state lighting|security, diag northbridge, selftest, events, faults, clear, monitor on|off, quit\n> "<<std::flush;bool running=true,monitor=true;pollfd input{0,POLLIN,0};std::string line;while(running){const auto now=now_ms();bike::Packet p{};while(node.poll(p,now)){supervisor.observe(p,now);const auto decoded=decode(p);logger.record(now,p,decoded);test.observe(p,node,supervisor,now);if(monitor)std::cout<<'['<<now<<"] "<<name(p.source)<<" -> "<<name(p.destination)<<" "<<decoded<<"\n";}test.service(node,supervisor,now);report(test);supervisor.service(now);node.service(now);const int ready=::poll(&input,1,10);if(ready>0&&(input.revents&POLLIN)){if(!std::getline(std::cin,line))break;if(line=="quit"||line=="exit")running=false;else if(line=="scan")supervisor.send_discovery(now);else if(line=="inventory"){for(const auto& s:supervisor.nodes())if(s.discovered)std::cout<<name(s.address)<<" online="<<s.online<<" faults="<<s.fault_count<<" reboots="<<s.reboot_count<<"\n";}else if(line=="selftest"){if(test.active())std::cout<<"Self-test already running\n";else test.begin(node,supervisor,now);report(test);}else if(line=="monitor on")monitor=true;else if(line=="monitor off")monitor=false;else if(line=="events"||line=="faults"){for(const auto& e:logger.events()){if(line=="faults"&&e.type!=bike::MessageType::Fault&&e.type!=bike::MessageType::FaultClear&&e.type!=bike::MessageType::LightingDiagnostic)continue;std::cout<<'['<<e.time_ms<<"] "<<name(e.source)<<" "<<e.text<<"\n";}}else if(line=="clear")logger.clear();else if(line=="diag northbridge")request(node,bike::NodeAddress::Northbridge,bike::MessageType::Diagnostic,now);else if(line=="state lighting")request(node,bike::NodeAddress::Lighting,bike::MessageType::GetState,now);else if(line=="state security")request(node,bike::NodeAddress::Security,bike::MessageType::GetState,now);else if(!line.empty())std::cout<<"Unknown command\n";if(running)std::cout<<"> "<<std::flush;}}return 0;}
